/* Data Engineer Fieldnotes. No backend, tracking, remote scripts or API keys. */
(function () {
'use strict';
const D=globalThis.FIELDNOTES_DATA,C=globalThis.FieldCore,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
if(!D||!C||!globalThis.FieldLoader||!globalThis.FieldStudyUI||!globalThis.FieldAttention){$('#main').innerHTML='<h1>The study pack could not load.</h1><p>Keep the assets folder beside index.html, then reload.</p>';return;}
const KEY='data-engineer-fieldnotes.v1',Q=Object.fromEntries(D.questions.map(q=>[q.id,q])),L=Object.fromEntries(D.lessons.map(l=>[l.id,l])),G=Object.fromEntries(D.glossary.map(g=>[g.id,g]));
const loader=globalThis.FieldLoader.create(D,fetch.bind(window),document.baseURI,()=>lang);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const doclink=(id)=>{const s=D.sources[id];return s?`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`:'';};
const sourceKind=s=>s.kind==='community'?'Community · secondary':s.kind==='provider-course'?'Provider course':'Primary source';
const refs=ids=>`<ul class="source-list">${[...new Set(ids)].map(id=>D.sources[id]?`<li>${doclink(id)}<small>${e(D.sources[id].publisher)} · ${sourceKind(D.sources[id])}</small></li>`:'').join('')}</ul>`;
const tag=(text,color='')=>`<span class="chip ${color}">${e(text)}</span>`;
const qlabel=q=>q.origin==='authored'?`Practice ${String(q.number).padStart(2,'0')}`:`Imported #${q.number}`;
const domain=id=>D.domains.find(d=>d.id===Number(id));
const domainLessons=id=>D.lessons.filter(l=>l.domain===id);
function load(){try{const raw=localStorage.getItem(KEY);if(raw)return C.validateProgress(JSON.parse(raw),Object.keys(L),Object.keys(Q),Object.keys(G),D.workshops);}catch(error){try{const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'.recovery',raw);}catch{}}return C.defaultState();}
let state=load(),storageWarned=false,toastTimer,route='',practice={id:null,selected:[],checked:false},bank={query:'',domain:0,origin:'all',status:'all',difficulty:'all',saved:false,incorrect:false,page:1},english={query:'',saved:false,mode:'list',index:0,flipped:false,deck:[]},lab={tab:'stream',step:0,late:3,days:7,country:'CL',recipe:'stream'},sourceQuery='';
const U=globalThis.FieldStudyUI.create({D,e,refs,tag,doclink,getState:()=>state,save,render});
const A=globalThis.FieldAttention.create({D,C,e,refs,tag,getState:()=>state,save,render,highlight});
let N;const entryUI=()=>N||(N=globalThis.FieldEntry?.create({D,C,e,tag,render,setPracticeDomain:id=>{bank.domain=id;bank.page=1;}}));
let focusMode=false;try{focusMode=C.parseFocusPreference(localStorage.getItem(C.FOCUS_KEY));}catch{}
function focusFraction(){if(route==='focus')return C.focusProgress((state.focus?.step||0)+1,4);if(route==='learn')return C.focusProgress(state.completed.length,D.lessons.length);return null;}
function updateFocus(){const on=focusMode,bar=$('#focus-progress'),f=on?focusFraction():null;document.body.classList.toggle('focus-session',route==='focus'||on);$('#focus-toggle').setAttribute('aria-pressed',String(on));$('#focus-status').textContent=on?'on':'off';bar.hidden=f===null;if(f!==null){bar.setAttribute('aria-valuenow',String(Math.round(f*100)));bar.firstElementChild.style.width=f*100+'%';}}
function setFocus(on){focusMode=on;try{localStorage.setItem(C.FOCUS_KEY,C.serializeFocusPreference(on));}catch{}updateFocus();}
let lang='en';try{lang=C.parseLang(localStorage.getItem(C.LANG_KEY));}catch{}
let i18nLoad;
function applyLang(){document.documentElement.lang=lang;$('#lang-toggle').setAttribute('aria-pressed',String(lang==='es'));if(lang!=='es'){globalThis.FieldI18n?.stop();return;}i18nLoad=i18nLoad||new Promise((ok,no)=>{const s=document.createElement('script');s.src='assets/i18n.js?v='+D.release;s.onload=ok;s.onerror=no;document.head.append(s);}).catch(x=>{i18nLoad=null;throw x;});i18nLoad.then(()=>lang==='es'&&globalThis.FieldI18n.start(D.release)).catch(()=>{});}
function setLang(next){lang=next;try{localStorage.setItem(C.LANG_KEY,C.serializeLang(next));}catch{}applyLang();if(['learn','focus','home','review','progress','practice','workshops','sources','search','orientation','diagnostic'].includes(route))render(false);}
let renderVersion=0,currentView='',examReady=!state.exam;
function applyTheme(){const preference=state.theme||'system';document.documentElement.dataset.theme=preference==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):preference;$('#theme-toggle').textContent='Theme: '+preference;$('#theme-toggle').setAttribute('aria-label','Color theme: '+preference+'. Change theme');}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarned){storageWarned=true;toast('Browser storage is unavailable. Export progress before closing this page.');}}}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',learn:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3Z"/><path d="M12 6v16"/>',practice:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="m8 9 2 2 4-4M8 16h8"/>',english:'<path d="m3 18 5-13 5 13M5 14h6M14 7h7M18 4v3M14 12l6 8M21 8c0 5-3 9-7 11"/>',lab:'<path d="M8 3h8M10 3v7L4 20h16l-6-10V3M7 15h10"/>',exam:'<circle cx="12" cy="13" r="8"/><path d="M12 8v5l3 2M9 2h6"/>',sources:'<path d="M5 3h10l4 4v14H5Z"/><path d="M14 3v5h5M8 12h8M8 16h8"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.learn}</svg>`;
function renderNav(active){
 const primary=[['home','Start here'],['missions','Quick challenges'],['learn','Learning path'],['progress','My progress']];
 const tools=[['practice','Practice bank'],['english','English studio'],['lab','Interactive labs'],['compare','Compare services'],['architectures','Architecture explorer'],['workshops','Guided workshops'],['resources','Study resources'],['exam','Timed practice'],['sources','Sources & review']];
 const link=([key,label])=>`<a class="nav-item ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='practice'?`<span class="nav-count">${D.questions.length}</span>`:''}</a>`;
 $('#navigation').innerHTML=primary.map(link).join('')+`<details class="nav-tools" ${tools.some(t=>t[0]===active)?'open':''}><summary>More study tools</summary>${tools.map(link).join('')}</details>`;
 $('#breadcrumb').textContent=active==='focus'?'Short session':[...primary,...tools].find(n=>n[0]===active)?.[1]||'Search';
 $('#english-toggle').setAttribute('aria-pressed',String(state.english));$('#english-status').textContent=state.english?'on':'off';document.body.classList.toggle('english-off',!state.english);
 document.body.classList.toggle('focus-session',active==='focus'||focusMode);
}

function pipelineVisual(){return `<div class="pipeline-visual" role="img" aria-label="A streaming analytics route: devices publish to Pub/Sub, Dataflow transforms events, and BigQuery stores the analytical output."><div class="visual-top"><span>A RECORD’S JOURNEY</span><span>STREAMING PATTERN</span></div><svg viewBox="0 0 430 253"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#94a8ce" stroke-width="1"/></marker></defs><path d="M163 72H266M320 106V159M266 194H163" stroke="#9db2d8" fill="none" stroke-width="1.2" marker-end="url(#arrow)" class="flow-line"/><g fill="#fff" stroke="#d8e2f2"><rect x="23" y="38" width="140" height="68" rx="9"/><rect x="266" y="38" width="140" height="68" rx="9"/><rect x="266" y="159" width="140" height="68" rx="9"/><rect x="23" y="159" width="140" height="68" rx="9"/></g><g font-size="8" fill="#8592a8"><text x="195" y="62">publish</text><text x="327" y="139">transform</text><text x="188" y="185">write output</text></g><g fill="#3159c9"><rect x="35" y="53" width="25" height="25" rx="6" fill="#edf2ff"/><path d="M41 60h13v12H41zM45 64h5" fill="none" stroke="#3159c9"/><rect x="278" y="53" width="25" height="25" rx="6" fill="#edf2ff"/><circle cx="286" cy="61" r="2"/><circle cx="296" cy="61" r="2"/><circle cx="291" cy="71" r="2"/><path d="m286 63 5 6 5-6" stroke="#3159c9" fill="none"/><rect x="278" y="174" width="25" height="25" rx="6" fill="#fff4db"/><path d="M284 181h13M284 187h13M284 193h13" stroke="#b98c36"/><rect x="35" y="174" width="25" height="25" rx="6" fill="#e9f5f1"/><path d="M41 193v-8M47 193v-13M53 193v-5" stroke="#2b8773" stroke-width="2"/></g><g font-size="11" font-weight="650" fill="#334660"><text x="69" y="62">Device events</text><text x="312" y="62">Pub/Sub</text><text x="312" y="183">Dataflow</text><text x="69" y="183">BigQuery</text></g><g font-size="8" fill="#8490a4"><text x="69" y="78">Preserve event time</text><text x="312" y="78">Decouple producers</text><text x="312" y="199">Validate · window</text><text x="69" y="199">Store · analyze</text></g><text x="215" y="245" text-anchor="middle" font-size="7" fill="#8c99ad">ONE USEFUL PATTERN. THE REQUIREMENTS MAKE THE DECISION.</text></svg></div>`;}
function renderHome(){return (entryUI()?.panel()||'')+A.welcome();}

function storageComparison(){return `<section class="lesson-section"><h2>Compare the storage choices</h2><p class="small muted">Use the access pattern as the first filter, then verify consistency, availability and cost.</p><div class="table-wrap"><table><caption class="sr-only">Data storage decision guide</caption><thead><tr><th>Service</th><th>Good fit and exam signal</th><th>Check the assumption</th></tr></thead><tbody>${D.services.filter(s=>s.category==='Storage').map(s=>`<tr><td><strong>${e(s.name)}</strong><br>${doclink(s.reference)}</td><td data-english>${e(s.fit)}<br><span class="muted">${e(s.signal)}</span></td><td data-english>${e(s.caution)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderLearn(id){if(!id||!L[id])return `<div class="page-heading"><div><div class="eyebrow">A SYSTEMATIC STUDY ROUTE</div><h1>Learn the decisions.<br>Then learn the services.</h1><p class="lead">${D.lessons.length} expanded lessons across all 19 standard-guide objectives. Work through core concepts, deeper decisions, retrieval exercises and primary references.</p></div><a class="button" href="#exam">Check your understanding →</a></div><div class="path-grid">${D.domains.map(d=>`<section class="path-section" style="--accent:${d.color}"><div class="path-section-top"><span class="domain-index">0${d.id}</span><div><h2>${e(d.name)}</h2><div class="small muted">~${d.weight}% of the exam · ${e(d.subtitle)}</div></div></div>${domainLessons(d.id).map(l=>`<a href="#learn/${l.id}" class="lesson-row"><span class="lesson-check ${state.completed.includes(l.id)?'done':''}">${state.completed.includes(l.id)?'✓':''}</span><span class="lesson-info">${e(l.title)}<span class="meta">Objective ${l.objective} · ${l.level} · ${l.minutes} min</span></span><span aria-hidden="true">↗</span></a>`).join('')}</section>`).join('')}</div>`;
const l=L[id],idx=D.lessons.indexOf(l),next=D.lessons[idx+1],done=state.completed.includes(id),related=D.questions.filter(q=>q.origin==='authored'&&q.lesson===id).slice(0,3);
return `<a href="#learn" class="back-link">← All lessons</a><div class="study-grid"><article class="lesson-body"><div class="eyebrow">DOMAIN 0${l.domain} · OBJECTIVE ${l.objective}</div><h1>${e(l.title)}</h1><p class="lead" data-english>${e(l.lead)}</p><div class="meta">${tag(l.minutes+' minute lesson','blue')}${tag(l.level)}${tag(done?'Completed':'Ready when you are',done?'green':'')}</div>${globalThis.FieldLessonBlock?(globalThis.FieldLessonBlock.current=l,globalThis.FieldLessonBlock.render(l)):''}${A.briefingPanel(l)}${U.evidencePanel(l)}${l.sections.map(s=>`<section class="lesson-section"><h2>${e(s.title)}</h2><p data-english>${e(s.body)}</p>${s.references?.length?`<details class="section-evidence"><summary>Check this explanation</summary>${refs(s.references)}</details>`:''}</section>`).join('')}${l.id==='storage-choice'?storageComparison():''}${l.code?`<div class="code-head"><span>ILLUSTRATIVE EXAMPLE</span><button class="button small" data-action="copy-code" data-id="${id}">Copy example</button></div><pre><code>${e(l.code)}</code></pre>`:''}${l.exercise?`<section class="retrieval-exercise"><div class="eyebrow">RECALL BEFORE REVEALING</div><h2>Explain the decision</h2><p data-english>${e(l.exercise.prompt)}</p><details><summary>Compare your reasoning</summary><p data-english>${e(l.exercise.answer)}</p><ul>${l.exercise.checkpoints.map(c=>`<li data-english>${e(c)}</li>`).join('')}</ul></details></section>`:''}${D.workshops.some(w=>w.lessons.includes(id))?`<section class="lesson-section"><h2>Try a guided workshop</h2><div class="stack">${D.workshops.filter(w=>w.lessons.includes(id)).map(w=>`<a class="button" href="#workshops/${w.id}">${e(w.title)} →</a>`).join('')}</div></section>`:''}<aside class="trap"><h3>Watch the assumption</h3><p data-english>${e(l.trap)}</p></aside><div class="lesson-end"><button class="button ${done?'':'primary'}" data-action="complete" data-id="${id}">${done?'✓ Completed · mark incomplete':'Mark lesson complete'}</button><a href="${next?'#learn/'+next.id:'#home'}" class="button">${next?'Next lesson →':'Return to overview →'}</a></div></article><aside class="study-side"><section class="panel"><h3>Go to the source</h3><p class="muted">Read the official detail after understanding the principle.</p>${refs(l.references)}<p class="muted credit">Based on the official Google Cloud documentation linked above. Check each page for its license terms. This site is independent and not affiliated with Google.</p></section><section class="panel english-card"><h3>Learn in English, understand deeply</h3><p lang="es">Toca las palabras subrayadas para ver su significado, traducción y pronunciación. Guarda las difíciles en tu vocabulario.</p><a href="#english" class="text-link">Open English studio →</a></section>${related.length?`<section class="panel"><h3>Put the idea to work</h3><div class="stack">${related.map(q=>`<a class="button small" href="#practice/${q.id}">${qlabel(q)} · try a scenario →</a>`).join('')}</div></section>`:''}</aside></div>`;}
function latestAttempts(verifiedOnly=false){const latest=new Map();for(const a of state.attempts)if(!verifiedOnly||a.verified)latest.set(a.id,a);return [...latest.values()];}
function filteredBank(){const wrong=new Set(latestAttempts().filter(a=>!a.correct).map(a=>a.id)),query=bank.query.trim().toLowerCase().replace(/^#/,'');return D.questions.filter(q=>(!bank.domain||q.domain===bank.domain)&&(bank.origin==='all'||q.origin===bank.origin)&&(bank.difficulty==='all'||q.difficulty===bank.difficulty)&&(bank.status==='all'||(bank.status==='needs-review'?q.status!=='reviewed'&&q.status!=='corrected':q.status===bank.status))&&(!bank.saved||state.bookmarks.includes(q.id))&&(!bank.incorrect||wrong.has(q.id))&&(!query||String(q.number)===query||(q.search+' '+q.text+' '+qlabel(q)).toLowerCase().includes(query)));}
function statusTag(q){if(q.origin==='authored')return tag((q.difficulty||'Foundation')+' · evidence-linked','green');return tag({reviewed:'Editorial review',corrected:'Key corrected',disputed:'Key disputed',incomplete:'Missing diagram',legacy:'Legacy wording',conditional:'Conditional answer',unreviewed:'Source key only'}[q.status]||q.status,q.status==='reviewed'?'green':q.status==='corrected'?'blue':q.status==='disputed'?'red':'amber');}
function questionRows(items){return items.map(q=>`<button class="question-row" data-action="open-question" data-id="${q.id}"><span class="question-number">${qlabel(q)}</span><span class="question-row-body"><span class="meta">${statusTag(q)}${tag(domain(q.domain).name)}${q.required>1?tag('Choose '+q.required):''}${state.bookmarks.includes(q.id)?tag('Saved','amber'):''}</span><h3>${e((q.text.length>1100?q.text.slice(-420):q.text).slice(0,230))}${q.text.length>230?'…':''}</h3></span><span class="row-arrow" aria-hidden="true">↗</span></button>`).join('');}
function bankResults(){const items=filteredBank(),pages=Math.max(1,Math.ceil(items.length/12));bank.page=Math.min(pages,bank.page);return `<div class="bank-meta"><span class="small muted">${items.length} questions · page ${bank.page} of ${pages}</span><button class="button quiet small" data-action="clear-bank">Clear filters</button></div>${items.length?`<div class="question-list">${questionRows(items.slice((bank.page-1)*12,bank.page*12))}</div><div class="pagination"><button class="button small" data-action="bank-page" data-dir="-1" ${bank.page===1?'disabled':''}>← Previous</button><span>${bank.page} / ${pages}</span><button class="button small" data-action="bank-page" data-dir="1" ${bank.page===pages?'disabled':''}>Next →</button></div>`:'<div class="empty"><h2>No questions match yet.</h2><p>Try a service name, a question number, or clear the filters.</p></div>'}`;}
function renderBank(){return `<div class="page-heading"><div><div class="eyebrow">PRACTICE WITH UNDERSTANDING</div><h1>Every answer needs a reason.</h1><p class="lead">All ${D.questions.length} questions: ${D.questions.filter(q=>q.origin==='imported').length} supplied imports and ${D.questions.filter(q=>q.origin==='authored').length} original scenarios. Source keys, review labels and original images remain available.</p></div><a href="#exam" class="button primary">Start timed practice ↗</a></div><div class="filterbar"><label class="field grow">FIND A QUESTION<input type="search" id="bank-query" value="${e(bank.query)}" placeholder="Try BigQuery, #243, event time…"></label><label class="field">DOMAIN<select id="bank-domain"><option value="0">All five domains</option>${D.domains.map(d=>`<option value="${d.id}" ${bank.domain===d.id?'selected':''}>0${d.id} · ${e(d.name)}</option>`).join('')}</select></label><label class="field">COLLECTION<select id="bank-origin">${[['all','All questions'],['imported','349 supplied questions'],['authored','124 original scenarios']].map(([v,t])=>`<option value="${v}" ${bank.origin===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">ORIGINAL LEVEL<select id="bank-difficulty">${[['all','Any level / imported'],['Foundation','Foundation originals'],['Applied','Applied originals']].map(([v,t])=>`<option value="${v}" ${bank.difficulty===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">REVIEW STATUS<select id="bank-status">${[['all','All statuses'],['reviewed','Reviewed'],['corrected','Corrected keys'],['needs-review','Needs review'],['disputed','Disputed keys'],['legacy','Legacy wording'],['incomplete','Missing diagrams']].map(([v,t])=>`<option value="${v}" ${bank.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="check-field"><input type="checkbox" id="bank-saved" ${bank.saved?'checked':''}>Saved questions</label><label class="check-field"><input type="checkbox" id="bank-incorrect" ${bank.incorrect?'checked':''}>Needs practice</label></div><div id="bank-results">${bankResults()}</div>`;}

function richHTML(html){return globalThis.FieldImageText.render(html,D.assets,e);}

function choicesHTML(q,selected,checked=false){return `<fieldset class="choices"><legend>${q.required>1?'Select exactly '+q.required+' options.':'Select one option.'}</legend>${q.choices.map(c=>{const picked=selected.includes(c.letter),right=checked&&q.answer.includes(c.letter),wrong=checked&&picked&&!right;return `<div class="choice ${picked?'selected':''} ${q.gradable&&right?'correct':''} ${q.gradable&&wrong?'wrong':''}" data-choice="${c.letter}"><input type="${q.required>1?'checkbox':'radio'}" name="answer" value="${c.letter}" id="answer-${c.letter}" aria-label="${e(c.letter+'. '+(c.transcription||c.text||globalThis.FieldImageText.textForHTML(c.html,D.assets)||'Original image alternative'))}" ${picked?'checked':''} ${checked?'disabled':''}><div id="choice-${c.letter}" class="choice-text rich" data-english><span class="choice-letter">${c.letter}.</span>${richHTML(c.html||e(c.transcription||c.text))}</div>${q.gradable&&checked&&(right||wrong)?`<span class="choice-result">${right?'✓ Correct':'× Selected'}</span>`:''}</div>`;}).join('')}</fieldset>`;}
function englishSide(text){const lower=text.toLowerCase(),matched=D.glossary.filter(g=>lower.includes(g.term.toLowerCase())).slice(0,9);return `<section class="panel english-card"><h3>The English behind the question</h3><p class="small" lang="es">Toca un término para aprender su significado y guardarlo.</p><div class="word-list">${(matched.length?matched:D.glossary.filter(g=>['v2','v4','v6'].includes(g.id))).map(g=>`<button class="word-pill" data-action="word" data-id="${g.id}">${e(g.term)}</button>`).join('')}</div></section>`;}
function feedback(q,selected){const match=C.equalAnswers(selected,q.answer),verified=q.gradable;return `<section class="answer-box" id="answer-feedback" tabindex="-1"><div class="answer-key">${tag(verified?(match?'✓ Your answer fits':'Review the decision'):(match?'Matches the imported key':'Differs from the imported key'),verified?(match?'green':'amber'):'amber')}${tag((q.status==='corrected'?'Editorial answer: ':'Answer key: ')+q.answer.join(', '),'blue')}</div><h2>${verified?'Why this answer fits':'Read the key with its limitations'}</h2>${q.status==='corrected'?`<div class="notice info">The source marked <strong>${q.sourceAnswer.join(', ')}</strong>. Editorial correction: <strong>${q.answer.join(', ')}</strong>. The original key is preserved.</div>`:''}<p data-english>${e(q.explanation||q.sourceExplanation)}</p>${q.origin==='imported'?`<p class="small muted">${e(q.reviewNote)}</p>`:''}${q.choices.some(c=>c.why)?`<h3 style="margin-top:24px">Check every alternative</h3>${q.choices.map(c=>`<div class="reason-row"><strong>${c.letter}${q.answer.includes(c.letter)?' ✓':''}</strong><p data-english>${e(c.why)}</p></div>`).join('')}`:''}${q.sourceExplanation&&q.explanation?`<details class="details"><summary>Read the original imported explanation</summary><p data-english>${e(q.sourceExplanation)}</p></details>`:''}<h3 style="margin-top:24px">${verified?'Documentation for the explanation':'Related official reading · not independent key validation'}</h3>${refs(q.references)}${q.sources.length?`<details class="details"><summary>Imported question provenance</summary>${q.sources.map(url=>`<p class="small"><a href="${e(url)}" target="_blank" rel="noopener noreferrer">ExamBase original question page ↗</a></p>`).join('')}<p class="small muted">Third-party practice material supplied in your archive. It is not represented as an official Google exam item.</p></details>`:''}</section>`;}
function questionBody(q){return q.text.length>2800?`<details class="case-study"><summary>Read the complete supplied case study and question</summary><div class="rich" data-english>${richHTML(q.html)}</div></details><p class="rich" data-english>${e(q.text.slice(-750))}</p>`:`<div class="rich" data-english>${richHTML(q.html)}</div>`;}
function renderQuestion(id){const q=Q[id];if(!q)return renderBank();if(practice.id!==id)practice={id,selected:[],checked:false};const saved=state.bookmarks.includes(id),idx=D.questions.indexOf(q),next=D.questions[(idx+1)%D.questions.length];return `<a href="#practice" class="back-link">← Back to question bank</a><div class="study-grid"><article class="question-card"><div class="question-toolbar"><div class="meta">${statusTag(q)}${tag('Domain 0'+q.domain)}</div><button class="button small" data-action="bookmark" data-id="${id}" aria-pressed="${saved}">${saved?'★ Saved':'☆ Save question'}</button></div><h1>${qlabel(q)}</h1>${!q.gradable?`<div class="notice ${q.status==='disputed'?'danger':''}">${q.status==='unreviewed'?'This key and its explanation are imported and not independently verified. Your selection is compared with the source, without counting it toward verified accuracy.':e(q.reviewNote)}</div>`:''}${q.issues.length?`<div class="notice">${q.issues.map(e).join('<br>')}</div>`:''}${questionBody(q)}${choicesHTML(q,practice.selected,practice.checked)}<div class="check-actions"><button class="button primary" data-action="${practice.checked?'retry-question':'check-answer'}">${practice.checked?'Try again':q.gradable?'Check my answer':'Compare with source key'}</button><a class="button" href="#practice/${next.id}">Next question →</a></div>${practice.checked?feedback(q,practice.selected):''}</article><aside class="study-side">${englishSide(q.text+' '+q.choices.map(c=>c.text).join(' '))}<section class="panel"><h3>Connect it to the concept</h3><p class="muted">${e(domain(q.domain).name)}</p><a class="text-link" href="#learn/${q.lesson}">${e(L[q.lesson]?.title||'Open a related lesson')} →</a></section><section class="panel"><h3>Separate the requirement from the clue</h3><p data-english>Identify the access pattern, latency target, consistency requirement and operational overhead. Choose the option satisfying all the stated constraints.</p></section></aside></div>`;}
function englishCards(){const list=D.glossary.filter(g=>(!english.saved||state.vocab[g.id])&&(!english.query||(g.term+' '+g.es+' '+g.meaning).toLowerCase().includes(english.query.toLowerCase())));return `<div class="small muted" style="margin-bottom:18px">${list.length} terms · ${Object.values(state.vocab).filter(v=>v.known).length} marked familiar</div><div class="vocab-grid">${list.map(g=>`<article class="vocab-card"><div class="meta">${tag('Technical + exam English','amber')}<button class="saved-star" data-action="save-word" data-id="${g.id}" aria-label="${state.vocab[g.id]?'Remove':'Save'} ${e(g.term)}" aria-pressed="${!!state.vocab[g.id]}">${state.vocab[g.id]?'★':'☆'}</button></div><h2>${e(g.term)}</h2><p>${e(g.meaning)}</p><details><summary>Spanish meaning</summary><span lang="es">${e(g.es)}</span></details><div class="vocab-actions"><button class="button small" data-action="word" data-id="${g.id}">Learn the phrase ↗</button><button class="button quiet small" data-action="speak" data-id="${g.id}" aria-label="Listen to ${e(g.term)}">▶ Listen</button></div></article>`).join('')}</div>${!list.length?'<div class="empty"><h2>Your wordbook starts with a word.</h2><p>Save any underlined term or clear the search to explore the glossary.</p></div>':''}`;}
function flashcard(){const saved=D.glossary.filter(g=>state.vocab[g.id]);if(!english.deck.length)english.deck=(saved.length?saved:D.glossary).map(g=>g.id);const pool=english.deck.map(id=>G[id]);english.index%=pool.length;const g=pool[english.index];return `<div class="small muted">${saved.length?'Your saved terms':'Exploring the complete glossary'} · card ${english.index+1} of ${pool.length}</div><section class="flashcard"><div class="mini-label">RECALL THE MEANING</div><h2>${e(g.term)}</h2>${english.flipped?`<p class="translation" lang="es">${e(g.es)}</p><p class="small muted">${e(g.meaning)}</p><p class="example">“${e(g.example)}”</p><div class="flash-actions"><button class="button" data-action="flash-again" data-id="${g.id}">Review again</button><button class="button primary" data-action="flash-known" data-id="${g.id}">I know this →</button></div>`:`<p class="small muted" lang="es">Recuerda el significado en español antes de revelar la respuesta.</p><div class="flash-actions"><button class="button primary" data-action="flip-card">Reveal meaning</button><button class="button" data-action="speak" data-id="${g.id}">▶ Listen</button></div>`}</section><p class="small muted" style="text-align:center">Familiarity is self-reported. Your saved terms and recall choices stay in this browser.</p>`;}
function renderEnglish(){return `<div class="page-heading"><div><div class="eyebrow">UNDERSTAND THE QUESTION, TOO</div><h1>Better English.<br>Clearer decisions.</h1><p class="lead">Learn technical vocabulary and the small phrases that change an exam requirement. Tap underlined language anywhere in your lessons and practice.</p></div><div class="meta">${tag(Object.keys(state.vocab).length+' saved words','amber')}</div></div><div class="tabs" role="tablist" aria-label="English study mode"><button class="tab ${english.mode==='list'?'active':''}" role="tab" aria-selected="${english.mode==='list'}" data-action="english-mode" data-mode="list">Wordbook · ${D.glossary.length} terms</button><button class="tab ${english.mode==='flash'?'active':''}" role="tab" aria-selected="${english.mode==='flash'}" data-action="english-mode" data-mode="flash">Recall cards</button></div>${english.mode==='list'?`<div class="filterbar"><label class="field grow">FIND A WORD OR MEANING<input type="search" id="term-search" placeholder="Try throughput, recuperar, while minimizing…" value="${e(english.query)}"></label><label class="check-field"><input type="checkbox" id="term-saved" ${english.saved?'checked':''}>Only my saved terms</label></div><div id="english-results">${englishCards()}</div>`:flashcard()}<details class="details" style="margin-top:28px"><summary>How to read a difficult exam sentence</summary><p data-english>“You need to ensure low latency while minimizing operational overhead.”</p><p lang="es"><strong>You need to ensure</strong> = debes garantizar. <strong>Low latency</strong> = poca demora. <strong>While minimizing</strong> = al mismo tiempo, reducir al mínimo. <strong>Operational overhead</strong> = esfuerzo continuo de administración.</p><p class="small muted" data-english>Plain English: deliver results quickly and choose an approach that is easy to operate. Both constraints matter.</p></details>`;}
const RECIPES={
 stream:{name:'Live sensor analytics',goal:'Analyze events continuously while keeping producers decoupled from processing.',steps:[['Devices','Timestamp each event at its source.','Preserve event IDs and the original event time.'],['Pub/Sub','Publish and buffer messages.','Subscriptions separate producer availability from downstream processing.'],['Dataflow','Validate, group and transform events.','Use Beam event-time windows and an explicit late-data policy.'],['BigQuery','Store the analytical result.','Choose a write contract and query-aligned table layout.']],refs:['dataflow','beam','write']},
 sql:{name:'Daily warehouse transformations',goal:'Build repeatable SQL models and reject invalid curated results.',steps:[['Source tables','Load a documented staging schema.','Define ownership, freshness and the meaning of each field.'],['Dataform','Version SQL and its dependencies.','Express models as a graph and reuse named definitions.'],['Assertions','Check the output contract.','Test unique keys, null rules and business conditions.'],['Curated tables','Publish validated analytical outputs.','Expose a documented data product through controlled access.']],refs:['dataform','dependencies','sharing']},
 spark:{name:'Existing Spark migration',goal:'Preserve an existing processing ecosystem under a short migration deadline.',steps:[['Existing jobs','Inventory dependencies and inputs.','Check library compatibility and required filesystem behavior.'],['Cloud Storage','Separate durable inputs from workers.','Retain documented files independently of cluster lifetime.'],['Dataproc / Spark','Run the existing processing model.','Compare job-based execution against persistent clusters.'],['Warehouse output','Validate and publish results.','Reconcile business totals before switching consumers.']],refs:['spark','transfer']},
 rag:{name:'A grounded document assistant',goal:'Retrieve relevant and permitted document context before generating an answer.',steps:[['Documents','Parse and split useful passages.','Keep source IDs, dates and access metadata with each chunk.'],['Embeddings','Represent chunk meaning numerically.','Use a consistent model and an appropriate retrieval strategy.'],['Retrieval','Find useful, authorized context.','Evaluate relevance and apply access restrictions.'],['Generation','Answer using retrieved evidence.','Preserve citations and evaluate the resulting answer.']],refs:['vectors','ai']}
};
function streamPanel(){const s=C.simulateStream(lab.step,lab.late);return `<div class="lab-grid"><section class="lab-controls"><label class="field">ALLOWED LATENESS<select id="lab-late">${[0,3,10].map(n=>`<option value="${n}" ${lab.late===n?'selected':''}>${n} minutes after window end</option>`).join('')}</select></label><div><button class="button primary" data-action="stream-next" ${lab.step===C.EVENTS.length?'disabled':''}>Process next event →</button></div><button class="button small" data-action="reset-lab">Reset experiment</button><p>Fixed five-minute windows. Window intervals include the start and exclude the end. Values are illustrative units.</p><p>In this teaching model, watermark = highest event time observed − 2 minutes, with a minimum of 0. A record is dropped when the previous watermark is at or beyond window end + allowed lateness. This is an explicit simulation rule, not Dataflow’s watermark algorithm.</p></section><section class="lab-display"><div class="meta">${tag('EVENT TIME ≠ ARRIVAL TIME','blue')}${tag('Watermark: '+s.watermark+' min')}</div><h2 style="margin-top:16px">Where does a delayed event belong?</h2><p class="small muted" data-english>Process the records in arrival order. Event D was created at minute 2 but arrives at minute 10. Compare 0 and 3 minutes of allowed lateness.</p><div class="event-queue" aria-label="Arrival-ordered events">${C.EVENTS.map((v,i)=>`<span class="event-token ${i<lab.step?(s.history[i].accepted?'done':'drop'):i===lab.step?'next':''}">${v.id}<small>t = ${v.time}</small></span>`).join('')}</div><div class="windows" aria-label="Window totals">${s.windows.map(w=>`<div class="window-box ${w.expired?'closed':''}"><h3>[${w.start}, ${w.end}) minutes</h3><strong>${w.total}</strong><p>Value units · ${w.ids.length?'events '+w.ids.join(', '):'no events yet'}</p>${tag(w.expired?'Expired':'Accepting allowed data',w.expired?'':'blue')}</div>`).join('')}</div><div class="metric-row"><div class="metric"><strong>${lab.step} / 6</strong><span>Events processed</span></div><div class="metric"><strong>${s.total}</strong><span>Accepted value units</span></div><div class="metric"><strong>${s.dropped}</strong><span>Dropped events</span></div></div><div class="notice info" aria-live="polite">${lab.step?(()=>{const h=s.history.at(-1);return `Event ${h.id}: created at ${h.time} min, arrived at ${h.arrival} min. Before arrival, the watermark was ${h.watermarkBefore} min. ${h.accepted?'Accepted into its event-time window'+(h.late?' despite its delay':'')+'.':'Dropped because its window had expired under the selected policy.'}`;})():'Start with event A. Change the allowed lateness to compare the same record sequence.'}</div>${s.history.length?`<div class="table-wrap"><table><caption class="sr-only">Processing history in arrival order</caption><thead><tr><th>Event</th><th>Event time</th><th>Arrival</th><th>Value</th><th>Decision</th></tr></thead><tbody>${s.history.map(h=>`<tr><td>${h.id}</td><td>${h.time} min</td><td>${h.arrival} min</td><td>${h.value}</td><td>${h.accepted?'Accepted':'Dropped'}${h.late?' · delayed':''}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="small" style="margin-top:20px">Read the model: ${doclink('beam')}</div></section></div>`;}
function scanPanel(){const m=C.scanModel(lab.days,lab.country);return `<div class="lab-grid"><section class="lab-controls"><label class="field">DAYS QUERIED: <strong id="day-count">${lab.days} / 30</strong><input type="range" id="scan-days" min="1" max="30" step="1" value="${lab.days}"></label><label class="field">COUNTRY FILTER<select id="scan-country"><option value="CL" ${lab.country==='CL'?'selected':''}>One country out of ten</option><option value="all" ${lab.country==='all'?'selected':''}>All countries</option></select></label><button class="button small" data-action="reset-lab">Reset experiment</button><p>Illustrative dataset: 30 days × 10 GB/day = 300 GB across the referenced columns. Ten countries have equal volumes.</p><p>The model assumes ideal date pruning and ideal country-block pruning. Real BigQuery storage blocks, query plans and billable bytes differ. These are teaching values, not a billing estimate.</p></section><section class="lab-display"><div class="eyebrow">READ LESS DATA, DO LESS WORK</div><h2>What changes when storage matches the query?</h2><p class="small muted" data-english>Hold the dataset and query columns fixed. Change the date range and country filter to compare three storage layouts.</p><div id="scan-output">${scanOutput(m)}</div><p class="small muted">Partitioning uses the date predicate. Clustering can further skip irrelevant country blocks. Actual clustered bytes are only known after execution.</p>${refs(['partition','cluster','prune'])}</section></div>`;}
function scanOutput(m){return `<div role="img" aria-label="Logical scan comparison: unorganized ${m.full} GB, partitioned ${m.partitioned} GB, partitioned and clustered ${m.clustered} GB.">${[['Unorganized layout',m.full,'#a2adc2'],['Date-partitioned',m.partitioned,'#7892d6'],['Partitioned + country-clustered',m.clustered,'#3159c9']].map(([name,n,color])=>`<div class="scan-row"><div class="scan-head"><span>${name}</span><strong>${Number(n.toFixed(1))} GB</strong></div><div class="scan-bar"><span style="--value:${100*n/300}%;--color:${color}"></span></div></div>`).join('')}</div><div class="notice success" aria-live="polite">In this idealized model, the combined layout reads ${Math.round((1-m.clustered/300)*100)}% fewer logical bytes than the unorganized layout.</div><pre><code>SELECT SUM(amount)
FROM demo.sales
WHERE event_date &gt;= DATE_SUB(DATE '2026-11-01', INTERVAL ${m.days} DAY)
  AND event_date &lt; DATE '2026-11-01'${lab.country==='all'?'':"\n  AND country = 'CL'"};</code></pre>`;}
function recipePanel(){const r=RECIPES[lab.recipe];return `<div class="lab-grid"><section class="lab-controls"><label class="field">BUSINESS SCENARIO<select id="recipe-select">${Object.entries(RECIPES).map(([id,v])=>`<option value="${id}" ${lab.recipe===id?'selected':''}>${e(v.name)}</option>`).join('')}</select></label><p>Follow one record or document through a complete pattern. The named transition on each step explains the relationship; other architectures may also satisfy different constraints.</p><a class="button small" href="#learn/processing-engine">Compare the engines →</a></section><section class="lab-display"><h2>${e(r.name)}</h2><p class="lead" data-english>${e(r.goal)}</p><div class="recipe-grid">${r.steps.map((s,i)=>`<article class="recipe-step"><div class="meta">${tag('STEP 0'+(i+1),'blue')}<span>${i===3?'Deliver the result':'Output becomes the next input →'}</span></div><h3>${e(s[0])}</h3><p><strong>${e(s[1])}</strong></p><p data-english style="margin-top:8px">${e(s[2])}</p></article>`).join('')}</div><h3 style="margin-top:25px">Check the details</h3>${refs(r.refs)}</section></div>`;}
function renderLab(){return `<div class="page-heading"><div><div class="eyebrow">MAKE THE CONCEPT VISIBLE</div><h1>Change one thing.<br>See what follows.</h1><p class="lead">Work through small, explicit models of streaming behavior and query layout. Every number and assumption is shown.</p></div></div><div class="tabs" aria-label="Choose an interactive lab">${[['stream','Late events & windows'],['scan','Partitioning & scanning'],['recipes','Architecture patterns']].map(([id,t])=>`<button class="tab ${lab.tab===id?'active':''}" data-action="lab-tab" data-id="${id}" aria-pressed="${lab.tab===id}">${t}</button>`).join('')}</div>${lab.tab==='stream'?streamPanel():lab.tab==='scan'?scanPanel():recipePanel()}`;}
function sourceCards(){const list=Object.values(D.sources).filter(s=>(s.title+' '+s.topic+' '+s.publisher).toLowerCase().includes(sourceQuery.toLowerCase()));return `<div class="small muted" style="margin-bottom:18px">${list.length} references · official, provider and secondary sources labelled</div><div class="source-grid">${list.map(s=>`<article class="source-card"><div class="meta">${tag(s.topic,'blue')}<span>${e(s.publisher)} · ${sourceKind(s)}</span></div><h3><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a></h3><div class="small muted">Editorial review · ${e(s.checked)}</div>${sourceAvailability(s.id)}</article>`).join('')}</div>`;}
function renderSources(){return `<div class="page-heading"><div><div class="eyebrow">TRACE THE REASONING</div><h1>Know where the answer comes from.</h1><p class="lead">Distinguish original educational notes, specific claims checked against official documentation, retained reviews and incomplete research inputs.</p></div></div><div class="download-row"><a class="button" href="#resources">Study resources →</a><a class="button" href="data/field-guide.md" download>Decision field guide ↓</a><a class="button primary" href="data/study-pack.json" download>Complete study pack · JSON ↓</a><a class="button" href="data/study-notes.md" download>Study notes · Markdown ↓</a><button class="button" data-action="export-progress">Export my progress ↓</button><button class="button" data-action="import-progress">Restore progress ↑</button></div><section class="panel"><h2>The official blueprint</h2><p>The ${D.lessons.length} lessons map to all 19 objectives in the standard guide. Coverage is a navigation aid, not a certification guarantee.</p><div class="table-wrap"><table><thead><tr><th>Study domain</th><th>Guide weight</th><th>Objectives</th></tr></thead><tbody>${D.domains.map(d=>`<tr><td><a href="#learn/${domainLessons(d.id)[0].id}">${e(d.name)}</a></td><td>~${d.weight}%</td><td>${Object.keys(d.objectives).join(' · ')}</td></tr>`).join('')}</tbody></table></div>${refs(['exam','guide'])}</section>${U.auditPanels()}<section class="panel detail-heading"><h2>The supplied question bank is preserved</h2><p>All 349 owner-supplied imported questions and their 25 original images remain in the practice bank, search and complete study download, alongside 124 original scenarios. The user confirmed that the owner supplied this collection. No source question or image has been removed or rewritten.</p><p>Ten text/code images and one table have visually checked selectable alternatives. Every original image remains available at full size. Review labels and source keys are preserved; readable transcription does not silently certify the answer.</p><p class="small muted">The original archive contains ten tiny placeholder images affecting eight questions. They are retained without inventing missing details. The 41 partial Path 16 provider quiz resources are a separate research input.</p></section><div class="section-head"><h2>The reference shelf</h2></div><div class="filterbar"><label class="field grow">FIND A SOURCE<input type="search" id="source-search" value="${e(sourceQuery)}" placeholder="Try security, streaming, BigQuery…"></label></div><div id="source-results">${sourceCards()}</div>`;}

function sourceAvailability(id){
 const r=D.sourceAudit.results.find(r=>r.id===id);
 return r?`<p class="small muted">Link ${r.available?'responded':'availability unconfirmed'} · ${e(D.sourceAudit.checkedOn)}${r.status?' · HTTP '+r.status:''}</p>`:'';
}
function serviceFieldGuide(){return `<div class="table-wrap"><table><caption>Requirements first: ${D.services.length} service choices</caption><thead><tr><th>Service / role</th><th>Useful fit and signal</th><th>Check before choosing</th></tr></thead><tbody>${D.services.map(s=>`<tr><td><strong>${e(s.name)}</strong><br>${tag(s.category)}<br>${doclink(s.reference)}</td><td data-english>${e(s.fit)}<br><span class="muted">${e(s.signal)}</span></td><td data-english>${e(s.caution)}</td></tr>`).join('')}</tbody></table></div>`;}
function renderResources(){
 const r=D.resources,s=r.standard,n=r.renewal;
 return `<div class="page-heading"><div><div class="eyebrow">A REFERENCED STUDY DESK</div><h1>Build depth.<br>Follow the evidence.</h1><p class="lead">Use the exam blueprint to set the scope, then learn, predict, explain and practise. Reviewed ${e(r.reviewedOn)}.</p></div><a class="button" href="data/field-guide.md" download>Decision field guide ↓</a></div>
 <section class="panel"><h2>Choose the right exam blueprint</h2><div class="table-wrap"><table><caption>Official exam information · check registration for current terms</caption><thead><tr><th>Detail</th><th>Standard exam</th><th>Renewal exam</th></tr></thead><tbody><tr><th>Duration</th><td>${s.minutes} minutes</td><td>${n.minutes} minutes</td></tr><tr><th>Questions</th><td>${s.questionRange}</td><td>${n.questions}</td></tr><tr><th>Registration fee</th><td>US$${s.feeUSD}</td><td>US$${n.feeUSD}</td></tr><tr><th>Languages</th><td>${s.languages.join(', ')}</td><td>${n.languages.join(', ')}</td></tr><tr><th>Domain weights (1 → 5)</th><td>${s.weights.map(w=>w+'%').join(' / ')}</td><td>${n.weights.map(w=>w+'%').join(' / ')}</td></tr><tr><th>Audience</th><td>First certification; no formal prerequisite.</td><td>${e(n.eligibility)}</td></tr></tbody></table></div><p class="small muted">Taxes may apply. Formats include multiple-choice and multiple-select items. This app’s learning path and timed allocation follow the standard guide.</p><p data-english><strong>Recommended experience:</strong> ${e(s.experience)}</p><p class="small muted">Standard certification validity: ${e(s.validity)}. Course access and certificates are separate from exam registration and certification.</p>${refs(['exam','guide','renewal-guide'])}</section>
 <div class="section-head"><h2>A self-paced route with observable outcomes</h2></div><p class="section-intro">Complete a block when you can explain its outcome using a fresh scenario. A checked box records your own study, not exam readiness.</p><div class="study-plan">${r.plan.map(b=>`<article class="panel plan-block"><h3>${e(b.title)}</h3><p data-english>${e(b.outcome)}</p><h4>Read and explain</h4><ul>${b.lessons.map(id=>`<li><a href="#learn/${id}">${e(L[id].title)}</a>${state.completed.includes(id)?' · completed':''}</li>`).join('')}</ul><h4>Predict and test</h4><ul>${b.workshops.map(id=>{const w=D.workshops.find(w=>w.id===id);return `<li><a href="#workshops/${id}">${e(w.title)}</a>${state.labProgress[id]?.completed?' · completed':''}</li>`;}).join('')}</ul></article>`).join('')}</div>
 <div class="section-head"><h2>Verified destinations, clear roles</h2></div><div class="resource-grid">${r.items.map(item=>`<article class="panel resource-card" id="resource-${item.id}"><div class="meta">${tag(item.type,'blue')}${tag(sourceKind(D.sources[item.source]))}</div><h3>${e(item.title)}</h3><p data-english>${e(item.use)}</p><p class="small"><strong>Access:</strong> ${e(item.access)}</p><p class="small muted">${e(item.caution)}</p>${doclink(item.source)}${sourceAvailability(item.source)}</article>`).join('')}</div>
 <div class="section-head"><h2>Keep a decision field guide</h2></div><p class="section-intro">Compare the access pattern, correctness contract and operational burden. Product names alone do not establish the answer.</p>${serviceFieldGuide()}
 <details class="details"><summary>What was checked and what each source means</summary><ul>${r.verificationNotes.map(note=>`<li>${e(note)}</li>`).join('')}</ul><p class="small muted">${e(D.sourceAudit.method)} ${e(D.sourceAudit.scope)}</p><a href="#sources">Inspect the reference shelf and knowledge audit →</a></details>`;
}
function workshopProgress(id){return state.labProgress[id]||(state.labProgress[id]={steps:[],prediction:'',revealed:false,completed:false});}
function workshopInput(f){
 if(f.type==='late')return {arrivalOrderedEvents:C.EVENTS,fixedWindowMinutes:5,allowedLatenessMinutes:[0,3],rule:'The previous watermark is the highest event time observed minus 2 minutes, floored at zero. Reject at or beyond window end plus allowed lateness.'};
 if(f.type==='scan')return {daysInDataset:30,gbPerDay:10,equalVolumeCountries:10,selectedDays:f.days,countryFilter:f.country,assumption:'Ideal partition and block pruning on the referenced columns; no billing estimate.'};
 if(f.type==='constraints')return {sentence:f.sentence};
 return f;
}
function renderWorkshops(id){
 const w=D.workshops.find(w=>w.id===id);
 if(!w)return `<div class="page-heading"><div><div class="eyebrow">PREDICT · RUN · EXPLAIN</div><h1>Turn the concept<br>into an observation.</h1><p class="lead">${D.workshops.length} guided exercises use small synthetic fixtures. Make a prediction, run the local model and explain the result. Steps and predictions survive a refresh.</p></div><a class="button" href="#resources">Follow the study route →</a></div><div class="notice info">These browser exercises create no Google Cloud resources. Use the official Google Skills path for hands-on experience in an actual cloud environment.</div><div class="workshop-grid">${D.workshops.map(item=>{const p=state.labProgress[item.id];return `<a class="panel workshop-card" href="#workshops/${item.id}"><div class="meta">${tag('Domain '+item.domain,'blue')}${tag(p?.completed?'Completed':(p?.steps.length||0)+' / '+item.steps.length+' steps',p?.completed?'green':'')}</div><h2>${e(item.title)}</h2><p data-english>${e(item.goal)}</p><span class="text-link">${item.minutes} min · open workshop →</span></a>`;}).join('')}</div>`;
 const p=workshopProgress(id),result=p.revealed?C.runWorkshop(w.fixture):null,complete=p.steps.length===w.steps.length&&p.revealed;
 return `<a class="back-link" href="#workshops">← All guided workshops</a><div class="study-grid"><article class="lesson-body"><div class="eyebrow">DOMAIN ${w.domain} · ${e(w.mode)}</div><h1>${e(w.title)}</h1><p class="lead" data-english>${e(w.goal)}</p><p class="small muted">${e(w.cloudNote)}</p><section class="lesson-section"><h2>1. Inspect the fixture</h2><p class="small muted">Synthetic input. Time values and rules belong to this example.</p><pre><code>${e(JSON.stringify(workshopInput(w.fixture),null,2))}</code></pre>${['late','scan'].includes(w.fixture.type)?'<a class="button small" href="#lab">Explore the interactive models →</a>':''}</section><section class="lesson-section"><h2>2. Work through the reasoning</h2><div class="workshop-checks">${w.steps.map(step=>`<label><input type="checkbox" data-workshop="${id}" data-step="${step.id}" ${p.steps.includes(step.id)?'checked':''}><span data-english>${e(step.text)}</span></label>`).join('')}</div></section><section class="prediction-box"><h2>3. Predict before running</h2><label class="field" for="workshop-prediction"><span data-english>${e(w.prediction.prompt)}</span><input id="workshop-prediction" data-workshop="${id}" value="${e(p.prediction)}" maxlength="300" autocomplete="off" placeholder="Your prediction" aria-describedby="prediction-unit"></label><p class="small muted" id="prediction-unit">Expected format: ${e(w.prediction.unit)}.</p><div class="check-actions"><button class="button" data-action="check-prediction" data-id="${id}">Check my prediction</button><button class="button primary" data-action="run-workshop" data-id="${id}">Run local fixture →</button></div><p id="prediction-feedback" role="status" aria-live="polite"></p></section>${result?`<section class="lesson-section" id="workshop-result"><h2>4. Explain the observed result</h2><div class="notice success">Computed result: <strong>${e(result.prediction)}${typeof result.prediction==='number'?' '+e(w.prediction.unit):''}</strong></div><pre><code>${e(JSON.stringify(result,null,2))}</code></pre><p data-english>${e(w.explanation)}</p><p class="small muted">This is a local teaching model. It demonstrates its stated rules; it does not measure Google Cloud service behavior.</p></section>`:''}${w.code?`<section class="lesson-section"><h2>Optional ${e(w.codeLanguage)} example</h2><p class="small muted">Read the example alongside the fixture. The local model above does not execute this code.</p><div class="code-head"><span>${e(w.codeLanguage)}</span><button class="button small" data-action="copy-workshop" data-id="${id}">Copy example</button></div><pre><code>${e(w.code)}</code></pre></section>`:''}<div class="lesson-end"><button class="button primary" data-action="complete-workshop" data-id="${id}" ${!complete&&!p.completed?'disabled':''}>${p.completed?'✓ Completed · mark incomplete':'Mark workshop complete'}</button><span class="small muted" id="workshop-completion-hint">Check all steps and run the fixture. Completion is self-reported.</span></div></article><aside class="study-side"><section class="panel"><h3>Revisit the concept</h3><ul class="source-list">${w.lessons.map(id=>`<li><a href="#learn/${id}">${e(L[id].title)} →</a></li>`).join('')}</ul></section><section class="panel"><h3>Verify the full behavior</h3>${refs(w.references)}</section><section class="panel english-card"><h3>Say the explanation in English</h3><p lang="es">Explica la condición, tu predicción y el resultado con tus propias palabras. Toca el vocabulario subrayado si necesitas ayuda.</p><a class="text-link" href="#english">Practise the language →</a></section></aside></div>`;
}
function finishExam(){const ex=state.exam;if(!ex)return;ex.finished=true;if(!ex.recorded){state.streak=C.touchStreak(state,C.localDate()).streak;const score=C.scoreExam(ex.ids,ex.answers,Q);for(const it of score.items)state.attempts.push({id:it.id,selected:it.picked,correct:it.correct,verified:true,at:Date.now()});state.attempts=state.attempts.slice(-2000);ex.recorded=true;}save();}
function examSetup(){return `<div class="page-heading"><div><div class="eyebrow">A QUIET PLACE TO PRACTICE</div><h1>Put your decisions<br>under a little pressure.</h1><p class="lead">A weighted set of original, evidence-linked questions. Save answers, move freely and review every explanation when you finish.</p></div></div><div class="exam-intro"><section class="exam-config"><h2>Set up your session</h2><p class="small muted">Choose a short drill or a full-length practice format.</p><label class="field">SESSION LENGTH<select id="exam-size"><option value="10">10 questions · 24 minutes</option><option value="20">20 questions · 48 minutes</option><option value="40" selected>40 questions · 120 minutes</option><option value="50">50 questions · 120 minutes</option></select></label><label class="field">ORIGINAL QUESTION LEVEL<select id="exam-difficulty"><option value="mixed">Mixed · ${D.questions.filter(q=>q.origin==='authored').length} original scenarios</option><option value="Applied">Applied · ${D.questions.filter(q=>q.difficulty==='Applied').length} scenarios</option><option value="Foundation">Foundation · ${D.questions.filter(q=>q.difficulty==='Foundation').length} scenarios</option></select></label><div class="notice info">Questions are sampled from the selected original learning pool. Domain allocation follows approximate official weights. This finite practice pool is not an official or predictive test.</div><button class="button primary" data-action="start-exam">Begin timed practice →</button></section><section class="panel"><h3>What to expect</h3><ul class="exam-guide"><li>Your session resumes after a refresh, with the original deadline.</li><li>Answers remain hidden until you finish or time runs out.</li><li>Use the numbered navigator to revisit any question.</li><li>Applied practice includes multiple-select items. Select exactly the stated number; scoring requires the complete correct set. Foundation practice uses single-select items.</li><li>Vocabulary help remains available as a learning aid. This is an open study session.</li></ul><a class="text-link" href="#sources">Review sources and question provenance →</a></section></div>`;}
function examResults(){const ex=state.exam,s=C.scoreExam(ex.ids,ex.answers,Q);return `<div class="page-heading"><div><div class="eyebrow">REVIEW IS WHERE LEARNING HAPPENS</div><h1>Make the next attempt better.</h1><p class="lead">Use the explanation to revise your reasoning. This score describes this practice session only.</p></div><button class="button primary" data-action="new-exam">Set up another session →</button></div><div class="study-grid"><section><div class="panel result-summary"><div class="score-ring"><strong>${s.percent}%</strong><span>${s.correct} / ${s.total} correct</span></div><p class="small muted">${s.unanswered} unanswered · all questions count equally · no partial credit</p><p class="small">No official passing score is implied.</p></div><div class="section-head"><h2>Review every decision</h2></div>${s.items.map((it,i)=>{const q=Q[it.id];return `<details class="result-row"><summary>${tag(it.correct?'✓ Correct':it.unanswered?'Unanswered':'Review',it.correct?'green':'amber')}<span>${i+1}. ${e(q.text.slice(0,120))}${q.text.length>120?'…':''}</span></summary><div class="result-explain"><h3 data-english>${e(q.text)}</h3><p class="small">Your selection: <strong>${it.picked.join(', ')||'None'}</strong> · Answer: <strong>${q.answer.join(', ')}</strong></p>${q.choices.map(c=>`<div class="reason-row"><strong>${c.letter}${q.answer.includes(c.letter)?' ✓':''}</strong><div><p>${e(c.text)}</p><p class="muted" data-english>${e(c.why)}</p></div></div>`).join('')}${refs(q.references)}<a class="text-link" href="#learn/${q.lesson}">Revisit the concept →</a></div></details>`;}).join('')}</section><aside class="study-side"><section class="panel"><h3>Performance by domain</h3>${D.domains.map(d=>{const v=s.domains[d.id]||{correct:0,total:0};return `<div style="margin:17px 0"><div class="scan-head"><span>${e(d.name)}</span><strong>${v.correct}/${v.total}</strong></div><div class="progress-track"><span class="progress-fill" style="--value:${v.total?100*v.correct/v.total:0}%"></span></div></div>`;}).join('')}</section><section class="panel english-card"><h3>Read the requirement again</h3><p lang="es">Antes de repetir, identifica qué palabra o condición cambió la decisión: consistencia, latencia, costo o administración.</p><a class="text-link" href="#english">Practice English recall →</a></section></aside></div>`;}
function renderExam(){const ex=state.exam;if(!ex)return examSetup();if(ex.deadline<=Date.now()&&!ex.finished)finishExam();if(ex.finished)return examResults();const q=Q[ex.ids[ex.index]],picked=ex.answers[q.id]||[];return `<div class="exam-header"><div><div class="eyebrow">TIMED PRACTICE · ORIGINAL SCENARIOS</div><h1>Question ${ex.index+1} <span class="muted">/ ${ex.ids.length}</span></h1><div class="meta">${tag(domain(q.domain).name,'blue')}<span>Answers are hidden until the session ends.</span></div></div><div id="exam-timer" class="exam-timer" role="timer" aria-label="Time remaining">${timeLeft(ex.deadline)}</div></div><div class="study-grid"><article class="question-card">${questionBody(q)}${choicesHTML(q,picked,false)}<div class="check-actions"><button class="button" data-action="exam-move" data-dir="-1" ${ex.index===0?'disabled':''}>← Previous</button>${ex.index<ex.ids.length-1?'<button class="button primary" data-action="exam-move" data-dir="1">Save & next →</button>':'<button class="button primary" data-action="finish-exam">Finish & review →</button>'}</div></article><aside class="study-side"><section class="panel"><h3>Question navigator</h3><p class="small muted">${Object.values(ex.answers).filter(a=>a.length).length} answered · blue fill means an answer is saved.</p><div class="exam-nav">${ex.ids.map((id,i)=>`<button data-action="exam-jump" data-index="${i}" class="${ex.answers[id]?.length?'answered':''} ${ex.index===i?'current':''}" aria-label="Question ${i+1}${ex.answers[id]?.length?', answered':''}${ex.index===i?', current':''}" ${ex.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><button class="button small" style="width:100%;margin-top:20px" data-action="finish-exam">Finish session</button></section>${englishSide(q.text)}</aside></div>`;}
function timeLeft(deadline){const n=Math.max(0,Math.ceil((deadline-Date.now())/1000));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function renderSearch(term){return U.renderSearch(term);}

const termByText=new Map(D.glossary.map(g=>[g.term.toLowerCase(),g]));
const termRegex=new RegExp('\\b('+D.glossary.map(g=>g.term).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\b','gi');
function highlight(root=$('#main')){if(!state.english)return;for(const el of root.querySelectorAll('[data-english]')){const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT,{acceptNode(n){return n.parentElement.closest('button,a,code,pre,script,style,summary,textarea,svg,label')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT;}}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){const text=node.nodeValue;termRegex.lastIndex=0;let match,index=0,fragment=document.createDocumentFragment(),found=false;while((match=termRegex.exec(text))){found=true;fragment.append(document.createTextNode(text.slice(index,match.index)));const g=termByText.get(match[0].toLowerCase()),button=document.createElement('button');button.type='button';button.className='term';button.dataset.action='word';button.dataset.id=g.id;button.textContent=match[0];button.setAttribute('aria-label',`Learn “${match[0]}” in English and Spanish`);fragment.append(button);index=match.index+match[0].length;}if(found){fragment.append(document.createTextNode(text.slice(index)));node.replaceWith(fragment);}}}}
async function render(scroll=false){
 const version=++renderVersion;let parts;
 try{parts=(location.hash.slice(1)||'home').split('/').map(decodeURIComponent);}catch{parts=['home'];}
 const target=parts[0],view=parts.join('/'),active=document.activeElement;
 const focus=active&&active!==document.body?{id:active.id,action:active.dataset?.action,item:active.dataset?.id}:null;
 route=target;renderNav(route);applyTheme();
 if(currentView!==view){$('#main').innerHTML='<div class="loading-view" role="status"><h1>Loading your study section…</h1><p>Only this section’s content is requested.</p></div>';}
 $('#main').setAttribute('aria-busy','true');
 let html;
 try{
  await loader.ensure(target,parts[1]);
  if(version!==renderVersion)return;
  switch(target){
   case'home':html=renderHome();break;
   case'orientation':case'diagnostic':case'review':html=await entryUI()[target](parts[1]);break;
   case'missions':html=A.renderMissions(parts[1]);break;
   case'focus':html=A.renderFocus(parts[1]);break;
   case'learn':html=renderLearn(parts[1]);break;
   case'practice':html=parts[1]?renderQuestion(parts[1]):renderBank();break;
   case'english':html=renderEnglish();break;
   case'lab':html=renderLab();break;
   case'compare':html=U.renderCompare(parts[1]);break;
   case'architectures':html=U.renderArchitectures(parts[1]);break;
   case'progress':html=U.renderProgress();break;
   case'workshops':html=renderWorkshops(parts[1]);break;
   case'resources':html=renderResources();break;
   case'exam':examReady=true;html=renderExam();break;
   case'sources':html=renderSources();break;
   case'search':html=renderSearch(parts.slice(1).join('/'));break;
   default:html=renderHome();route='home';
  }
 }catch(error){
  if(version!==renderVersion)return;
  console.error(error);
  html='<section class="empty" role="alert"><h1>This section could not load.</h1><p>Check the connection and retry. Saved study progress is kept in this browser.</p><button class="button primary" data-action="retry-content">Retry this section</button><p><a href="data/study-notes.md">Read the downloadable study notes</a></p></section>';
 }
 if(version!==renderVersion)return;
 currentView=view;$('#main').innerHTML=html;$('#main').removeAttribute('aria-busy');highlight();updateFocus();
 document.title=(route==='home'?'Learn with understanding':$('#main h1')?.textContent||'Study')+' · Data Engineer Fieldnotes';
 if(scroll){window.scrollTo({top:0,left:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
 else if(focus){const replacement=focus.id?document.getElementById(focus.id):focus.action?document.querySelector(`[data-action="${CSS.escape(focus.action)}"]${focus.item?`[data-id="${CSS.escape(focus.item)}"]`:''}`):null;replacement?.focus({preventScroll:true});}
 document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');
 if(target==='english'&&G[parts[1]])openWord(parts[1]);
}

function openWord(id){const g=G[id];if(!g)return;$('#vocab-content').innerHTML=`<button class="dialog-close" data-action="close-word" aria-label="Close vocabulary definition">×</button><div class="mini-label">ENGLISH FIELDNOTES</div><h2 id="vocab-title">${e(g.term)}</h2><p class="vocab-definition">${e(g.meaning)}</p><div class="translation-box"><div class="mini-label">EN ESPAÑOL</div><p lang="es">${e(g.es)}</p></div><p class="vocab-example">“${e(g.example)}”</p><div class="dialog-actions"><button class="button primary" data-action="save-word" data-id="${g.id}">${state.vocab[id]?'★ Saved · remove':'☆ Save to my wordbook'}</button><button class="button" data-action="speak" data-id="${id}">▶ Listen</button></div><p class="small muted" style="margin:18px 0 0">Pronunciation uses the speech voices available in your browser.</p>`;const dialog=$('#vocab-dialog');dialog.dataset.term=id;if(!dialog.open)dialog.showModal();}
function speak(id){if(!('speechSynthesis'in window)||!G[id]){toast('Pronunciation is unavailable in this browser. The definition and example remain available.');return;}const text=new SpeechSynthesisUtterance(G[id].term),voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)text.voice=voice;text.lang='en-US';text.rate=.83;text.onerror=()=>toast('This browser could not play speech. Try an installed English voice.');speechSynthesis.cancel();speechSynthesis.speak(text);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function syncChoice(target){const ex=route==='exam'&&state.exam&&!state.exam.finished,q=ex?Q[state.exam.ids[state.exam.index]]:Q[practice.id];if(!q||(!ex&&practice.checked))return;let selected=$$('.choices input:checked').map(i=>i.value);if(ex){state.exam.answers[q.id]=selected;save();const idx=state.exam.index,button=$(`.exam-nav button[data-index="${idx}"]`);button?.classList.toggle('answered',selected.length>0);}else practice.selected=selected;$$('.choice').forEach(el=>el.classList.toggle('selected',selected.includes(el.dataset.choice)));}
document.addEventListener('click',async ev=>{
 if(ev.target.closest('.skip')){ev.preventDefault();$('#main').focus();return;}
 const button=ev.target.closest('button[data-action]');
 if(!button){const option=ev.target.closest('.choice');if(option&&!ev.target.closest('input,button,a,summary,details')){if(window.getSelection()?.toString())return;const input=option.querySelector('input');if(!input.disabled)input.click();}return;}
 const action=button.dataset.action,id=button.dataset.id;
 if(A.onAction(button)||U.onAction(button)||N?.onAction(button))return;
 switch(action){
 case'retry-content':render(false);break;
 case'copy-image-text':try{const t=D.assets[button.dataset.file]?.transcription;if(t){await navigator.clipboard.writeText(globalThis.FieldImageText.copyText(t));toast('Image text copied.');}}catch{toast('Select the text to copy it.');}break;
 case'word':openWord(id);break;
 case'close-word':$('#vocab-dialog').close();break;
 case'speak':speak(id);break;
 case'save-word':if(state.vocab[id])delete state.vocab[id];else state.vocab[id]={saved:true,known:false};save();if(route==='english')render(false);if($('#vocab-dialog').open)openWord(id);else if(route!=='english')toast(state.vocab[id]?'Saved to your English wordbook.':'Removed from your wordbook.');break;
 case'complete':if(state.completed.includes(id))state.completed=state.completed.filter(x=>x!==id);else{state.completed.push(id);state.streak=C.touchStreak(state,C.localDate()).streak;}save();render(false);toast(state.completed.includes(id)?'Lesson complete. Your learning progress is saved.':'Lesson marked incomplete.');break;
 case'check-prediction':{const w=D.workshops.find(w=>w.id===id),p=workshopProgress(id);const feedback=$('#prediction-feedback');feedback.textContent=!p.prediction.trim()?'Enter a prediction first.':C.checkPrediction(p.prediction,C.runWorkshop(w.fixture).prediction)?'Your prediction matches the local model. Run it and explain why.':'Revisit the fixture rules, or run the model and compare the intermediate result.';break;}
 case'run-workshop':workshopProgress(id).revealed=true;save();render(false);$('#workshop-result')?.scrollIntoView({block:'nearest',behavior:'instant'});break;
 case'complete-workshop':{const p=workshopProgress(id),w=D.workshops.find(w=>w.id===id);if(!p.completed&&(!p.revealed||p.steps.length!==w.steps.length))break;p.completed=!p.completed;if(p.completed)state.streak=C.touchStreak(state,C.localDate()).streak;save();render(false);toast(p.completed?'Workshop marked complete. Your reasoning matters more than the checkbox.':'Workshop marked incomplete.');break;}
 case'copy-workshop':try{await navigator.clipboard.writeText(D.workshops.find(w=>w.id===id).code);toast('Example copied.');}catch{toast('Select the example text to copy it.');}break;
 case'copy-code':try{await navigator.clipboard.writeText(L[id].code||D.lessons.find(l=>l.id===id)?.code||'');toast('Illustrative example copied.');}catch{toast('Copy is unavailable here. Select the example text to copy it.');}break;
 case'open-question':location.hash='practice/'+id;break;
 case'clear-bank':bank={query:'',domain:0,origin:'all',status:'all',difficulty:'all',saved:false,incorrect:false,page:1};render(false);break;
 case'bank-page':bank.page=Math.max(1,bank.page+Number(button.dataset.dir));$('#bank-results').innerHTML=bankResults();$('#bank-results').scrollIntoView({block:'start'});break;
 case'bookmark':if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(x=>x!==id);else state.bookmarks.push(id);save();render(false);break;
 case'check-answer':{const q=Q[practice.id];if(practice.selected.length!==q.required){toast('Select exactly '+q.required+' option'+(q.required>1?'s.':'.'));break;}practice.checked=true;state.streak=C.touchStreak(state,C.localDate()).streak;state.attempts.push({id:q.id,selected:[...practice.selected],correct:C.equalAnswers(practice.selected,q.answer),verified:q.gradable,at:Date.now()});state.attempts=state.attempts.slice(-2000);save();render(false);$('#answer-feedback')?.focus({preventScroll:true});$('#answer-feedback')?.scrollIntoView({block:'nearest'});break;}
 case'retry-question':practice.selected=[];practice.checked=false;render(false);break;
 case'open-image':{const file=button.dataset.file;if(!D.assets[file])break;$('#image-content').innerHTML=`<img src="assets/images/${e(file)}" alt="Preserved original question diagram at its available resolution"><p>Original supplied image · ${D.assets[file].width} × ${D.assets[file].height} px. No missing content has been reconstructed.</p>`;$('#image-dialog').showModal();break;}
 case'close-image':$('#image-dialog').close();break;
 case'english-mode':english.mode=button.dataset.mode;english.flipped=false;english.index=0;english.deck=[];render(false);break;
 case'flip-card':english.flipped=true;render(false);break;
 case'flash-known':case'flash-again':state.vocab[id]={saved:true,known:action==='flash-known'};save();english.index++;english.flipped=false;render(false);break;
 case'lab-tab':lab.tab=id;render(false);break;
 case'stream-next':lab.step=Math.min(6,lab.step+1);render(false);break;
 case'reset-lab':lab={...lab,step:0,late:3,days:7,country:'CL'};render(false);break;
 case'export-progress':download('fieldnotes-progress.json',state);toast('Progress exported. Keep this file to move between browsers.');break;
 case'import-progress':$('#import-progress').click();break;
 case'start-exam':{const n=Number($('#exam-size').value);if(![10,20,40,50].includes(n))break;const now=Date.now(),minutes=n>=40?120:n*2.4,difficulty=$('#exam-difficulty').value;state.exam={difficulty,ids:C.makeExam(D.questions,n,D.domains,Math.random,difficulty),answers:{},index:0,startedAt:now,deadline:now+minutes*60000,finished:false,recorded:false};save();render(true);break;}
 case'exam-move':if(state.exam&&!state.exam.finished){state.exam.index=Math.max(0,Math.min(state.exam.ids.length-1,state.exam.index+Number(button.dataset.dir)));save();render(true);}break;
 case'exam-jump':if(state.exam&&!state.exam.finished){state.exam.index=Number(button.dataset.index);save();render(true);}break;
 case'finish-exam':finishExam();render(true);break;
 case'new-exam':state.exam=null;save();render(true);break;
 case'search-bank':bank.query=button.dataset.query;bank.page=1;location.hash='practice';break;
 }
 if(document.activeElement===document.body&&button.dataset.action&&!['check-answer','open-question','word','open-image'].includes(action)){
  const selector=`button[data-action="${CSS.escape(action)}"]${id?`[data-id="${CSS.escape(id)}"]`:''}`;
  const replacement=document.querySelector(selector);if(replacement&&!replacement.disabled)replacement.focus({preventScroll:true});
 }
});
document.addEventListener('input',ev=>{
 const id=ev.target.id;
 if(A.onInput(ev.target)||U.onInput(ev.target))return;
 if(id==='workshop-prediction'){workshopProgress(ev.target.dataset.workshop).prediction=ev.target.value;save();$('#prediction-feedback').textContent='';}
 if(id==='bank-query'){bank.query=ev.target.value;bank.page=1;$('#bank-results').innerHTML=bankResults();}
 if(id==='term-search'){english.query=ev.target.value;$('#english-results').innerHTML=englishCards();}
 if(id==='source-search'){sourceQuery=ev.target.value;$('#source-results').innerHTML=sourceCards();}
 if(id==='scan-days'){lab.days=Number(ev.target.value);$('#day-count').textContent=lab.days+' / 30';$('#scan-output').innerHTML=scanOutput(C.scanModel(lab.days,lab.country));}
});
document.addEventListener('change',async ev=>{
 const id=ev.target.id;
 if(A.onChange(ev.target)||U.onChange(ev.target))return;
 if(ev.target.matches('input[data-step]')){const p=workshopProgress(ev.target.dataset.workshop),step=ev.target.dataset.step;p.steps=ev.target.checked?[...new Set([...p.steps,step])]:p.steps.filter(s=>s!==step);save();const button=$('[data-action="complete-workshop"]'),w=D.workshops.find(w=>w.id===ev.target.dataset.workshop);if(button)button.disabled=!p.completed&&(!p.revealed||p.steps.length!==w.steps.length);return;}
 if(ev.target.matches('.choices input')){syncChoice(ev.target);return;}
 if(['bank-domain','bank-origin','bank-difficulty','bank-status','bank-saved','bank-incorrect'].includes(id)){
  if(id==='bank-domain')bank.domain=Number(ev.target.value);if(id==='bank-origin')bank.origin=ev.target.value;if(id==='bank-difficulty')bank.difficulty=ev.target.value;if(id==='bank-status')bank.status=ev.target.value;if(id==='bank-saved')bank.saved=ev.target.checked;if(id==='bank-incorrect')bank.incorrect=ev.target.checked;bank.page=1;$('#bank-results').innerHTML=bankResults();
 }
 if(id==='term-saved'){english.saved=ev.target.checked;$('#english-results').innerHTML=englishCards();}
 if(id==='lab-late'){lab.late=Number(ev.target.value);render(false);$('#lab-late').focus({preventScroll:true});}
 if(id==='scan-country'){lab.country=ev.target.value;$('#scan-output').innerHTML=scanOutput(C.scanModel(lab.days,lab.country));}
 if(id==='recipe-select'){lab.recipe=ev.target.value;render(false);$('#recipe-select').focus({preventScroll:true});}
 if(id==='import-progress'){const file=ev.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Progress files must be smaller than 2 MB.');const value=JSON.parse(await file.text());state=C.validateProgress(value,Object.keys(L),Object.keys(Q),Object.keys(G),D.workshops);examReady=!state.exam;if(state.exam){await loader.ensure('exam');examReady=true;}save();render(false);toast('Progress restored. Unknown items were ignored safely.');}catch(error){toast('Could not restore progress: '+error.message);}ev.target.value='';}
});
$('#global-search').addEventListener('submit',ev=>{ev.preventDefault();const value=$('#search-input').value.trim();if(value)location.hash='search/'+encodeURIComponent(value);});
$('#theme-toggle').addEventListener('click',()=>{const themes=['system','light','dark'];state.theme=themes[(themes.indexOf(state.theme||'system')+1)%themes.length];save();applyTheme();});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
$('#english-toggle').addEventListener('click',()=>{state.english=!state.english;save();render(false);toast(state.english?'English help is on. Tap underlined terms.':'English help is off. The wordbook is still available.');});
$('#focus-toggle').addEventListener('click',()=>setFocus(C.toggleFocus(focusMode)));
$('#lang-toggle').addEventListener('click',()=>setLang(C.toggleLang(lang)));
$('#menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));if(open)$('#navigation a').focus();});
document.addEventListener('keydown',ev=>{
 if(C.isFocusShortcut(ev)&&!ev.target.closest('dialog')){ev.preventDefault();setFocus(C.toggleFocus(focusMode));}
 if(ev.key==='Escape'&&focusMode&&!document.body.classList.contains('nav-open')&&!document.querySelector('dialog[open]'))setFocus(false);
 if(ev.key==='/'&&!ev.target.closest('input,textarea,select,[contenteditable=true],dialog')){ev.preventDefault();$('#search-input').focus();}
 if(ev.key==='Escape'&&document.body.classList.contains('nav-open')){document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').focus();}
 if(ev.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const tabs=[...ev.target.parentElement.querySelectorAll('[role=tab]')],idx=tabs.indexOf(ev.target),next=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(idx+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();document.querySelectorAll('[role=tab]')[next]?.focus();}
});
window.addEventListener('hashchange',()=>render(true));
setInterval(()=>{if(examReady&&state.exam&&!state.exam.finished){if(state.exam.deadline<=Date.now()){finishExam();if(route==='exam')render(false);else toast('Your timed session has ended. Review it in Timed practice.');}else{const el=$('#exam-timer');if(el){el.textContent=timeLeft(state.exam.deadline);el.classList.toggle('urgent',state.exam.deadline-Date.now()<300000);}}}},1000);
if(state.exam)loader.ensure('exam').then(()=>{examReady=true;}).catch(()=>toast('Your timed session will resume after its questions can load. Open Timed practice to retry.'));
applyLang();
render(false);
})();
